function countChars(text) {
  return Array.from(String(text ?? '')).length;
}

function escapeHtml(text) {
  return String(text ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function decodeBasicEntities(text) {
  return String(text ?? '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&laquo;/g, '«')
    .replace(/&raquo;/g, '»')
    .replace(/&mdash;/g, '—');
}

function normalizeText(text) {
  return String(text ?? '')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function prepareRawHtml(text) {
  let raw = String(text ?? '');

  // MAX использует HTML. Если AI всё же вернул Markdown,
  // переводим его в разрешённые HTML-теги ДО экранирования.
  raw = raw
    .replace(/\*\*\*([^*\n]+?)\*\*\*/g, '<b><i>$1</i></b>')
    .replace(/\*\*([^*\n]+?)\*\*/g, '<b>$1</b>')
    .replace(/__([^_\n]+?)__/g, '<b>$1</b>')
    .replace(/\*([^*\n]+?)\*/g, '<i>$1</i>')
    .replace(/```[\s\S]*?```/g, '')
    .replace(/`([^`]*)`/g, '$1')
    // Остаточные ASCII-звёздочки не должны уходить пользователю как Markdown-маркеры.
    .replace(/\*/g, '');

  return raw
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|h[1-6]|li)>/gi, '\n')
    .replace(/<(p|div|h[1-6])[^>]*>/gi, '\n')
    .replace(/<li[^>]*>/gi, '• ');
}

function tagName(tag) {
  const simple = String(tag).match(/^<\/?(b|i)>$/i);
  if (simple) return simple[1].toLowerCase();
  if (/^<a\s+href="[^"]+">$/i.test(String(tag))) return 'a';
  if (/^<\/a>$/i.test(String(tag))) return 'a';
  return '';
}

function sanitizeTag(tag, allowed) {
  const value = String(tag ?? '').trim();
  const simple = value.match(/^<\/?(b|i)>$/i);
  if (simple) {
    const name = simple[1].toLowerCase();
    if (!allowed.includes(name)) return '';
    return value.startsWith('</') ? `</${name}>` : `<${name}>`;
  }

  const a = value.match(/^<a\s+href="([^"]+)">$/i);
  if (a && allowed.includes('a')) {
    const href = escapeHtml(a[1]).replace(/&quot;/g, '');
    return `<a href="${href}">`;
  }

  if (/^<\/a>$/i.test(value) && allowed.includes('a')) return '</a>';

  return '';
}

function balanceHtml(html, allowed) {
  const tokens = String(html ?? '').split(/(<[^>]+>)/g).filter(v => v !== '');
  const stack = [];
  let out = '';

  for (const token of tokens) {
    if (token.startsWith('<') && token.endsWith('>')) {
      const safeTag = sanitizeTag(token, allowed);
      if (!safeTag) continue;
      const name = tagName(safeTag);
      const isClose = /^<\//.test(safeTag);

      if (!isClose) {
        stack.push(name);
        out += safeTag;
      } else if (stack[stack.length - 1] === name) {
        stack.pop();
        out += safeTag;
      }
    } else {
      out += token;
    }
  }

  while (stack.length) {
    out += `</${stack.pop()}>`;
  }

  return out;
}

function cleanHtml(text, allowed = ['b', 'i', 'a']) {
  const raw = prepareRawHtml(text);
  const tokens = raw.split(/(<[^>]+>)/g).filter(v => v !== '');
  let out = '';

  for (const token of tokens) {
    if (token.startsWith('<') && token.endsWith('>')) {
      out += sanitizeTag(token, allowed);
    } else {
      out += escapeHtml(decodeBasicEntities(token));
    }
  }

  return balanceHtml(normalizeText(out), allowed);
}

function stripTags(html) {
  return normalizeText(decodeBasicEntities(String(html ?? '').replace(/<[^>]+>/g, '')));
}

function countVisibleHtml(html) {
  return countChars(stripTags(html));
}

function collectHashtags(text) {
  const found = String(text ?? '').match(/#[\p{L}\p{N}_]+/gu) || [];
  const seen = new Set();
  const tags = [];

  for (const tag of found) {
    const clean = tag.replace(/[^\p{L}\p{N}_#]/gu, '').trim();
    const key = clean.toLowerCase();
    if (clean && !seen.has(key)) {
      seen.add(key);
      tags.push(clean);
    }
    if (tags.length >= 5) break;
  }

  return tags;
}

function removeHashtags(text) {
  return String(text ?? '')
    .replace(/#[\p{L}\p{N}_]+/gu, '')
    .replace(/[ \t]+\n/g, '\n')
    .trim();
}

const raw = $json.message?.content || $json.content || $json.text || '';
const thumbnail = $('Normalize Webhook or Manual Input').item.json.body.post_thumbnail;

let html = cleanHtml(raw, ['b', 'i', 'a']);
const hashtags = collectHashtags(stripTags(html));
html = cleanHtml(removeHashtags(html), ['b', 'i', 'a']);

const tagsLine = hashtags.join(' ');
const ctaHtml = '';
const separator = countVisibleHtml(html) && tagsLine ? '\n\n' : '';
const finalText = `${html}${ctaHtml}${separator}${escapeHtml(tagsLine)}`.trim();

if (finalText.includes('*')) {
  throw new Error('MAX_MARKDOWN_GUARD: после очистки в тексте остались ASCII-звёздочки. Публикация остановлена.');
}

return [{
  json: {
    text: finalText,
    max_text: finalText,
    max_length: countVisibleHtml(finalText),
    max_was_cut: false,
    max_hashtags: hashtags,
    max_hashtags_count: hashtags.length,
    max_html_preserved: true,
    thumbnail
  }
}];

