function titleKey(text) {
  return stripTags(String(text ?? ''))
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function removeLeadingDuplicateTitle(html, titleRaw) {
  const wanted = titleKey(titleRaw);
  if (!wanted) return normalizeText(html);

  const lines = normalizeText(html).split('\n');
  const firstIndex = lines.findIndex(line => stripTags(line).trim());
  if (firstIndex < 0) return normalizeText(html);

  const first = titleKey(lines[firstIndex]);
  const same =
    first === wanted ||
    (first.startsWith(wanted) && first.length <= wanted.length + 14) ||
    (wanted.startsWith(first) && wanted.length <= first.length + 14);

  if (same) {
    lines.splice(firstIndex, 1);
    while (lines.length && !stripTags(lines[0]).trim()) lines.shift();
  }

  return normalizeText(lines.join('\n'));
}

