function countChars(text) {
  return Array.from(String(text ?? '')).length;
}

function stripHtml(text) {
  return String(text ?? '').replace(/<[^>]+>/g, '');
}

function normalize(text) {
  return String(text ?? '')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const raw = $json.message?.content || $json.content || $json.text || '';
const text = normalize(stripHtml(raw));
const maxChars = 220;
const length = countChars(text);

if (length > maxChars) {
  throw new Error(
    `THREADS_RETRY_TOO_LONG: ${length}/${maxChars}. ` +
    `Retry-текст НЕ обрезан. Нужно перегенерировать его короче.`
  );
}

return [{
  json: {
    threads_text: text,
    threads_length: length,
    threads_limit: maxChars,
    threads_retry: true,
    threads_was_cut: false,
    threads_validated: true
  }
}];

const input = $input.first();
const incoming = input?.json || {};
const isManualExecution = $execution.mode === 'manual';

// Require the configured secret for non-manual webhook executions.
if (incoming?.body?.post && incoming.body.post.ID) {
  const expectedSecret = String($vars.CONTENT_OPS_WEBHOOK_SECRET || '').trim();
  const providedSecret = String(
    incoming.headers?.['x-content-ops-secret'] ||
    incoming.body?.secret ||
    incoming.body?.webhook_secret ||
    ''
  ).trim();
  if (!isManualExecution && !expectedSecret) {
    throw new Error('CONTENT_OPS_WEBHOOK_SECRET is not configured');
  }
  if (!isManualExecution && providedSecret !== expectedSecret) {
    throw new Error('Invalid webhook secret');
  }
  const safeIncoming = structuredClone(incoming);
  if (safeIncoming.body) {
    delete safeIncoming.body.secret;
    delete safeIncoming.body.webhook_secret;
  }
  return [{ json: { ...safeIncoming, __trigger_source: 'webhook' }, binary: input.binary }];
}

// Fixture for the Manual Trigger branch.
const manualPayload = {
  headers: {},
  params: {},
  query: {},
  body: {
    post_id: 1001,
    post: {
      ID: 1001,
      post_title: 'Three practical ways to improve cash-flow visibility',
      post_content: '<p>A fictional small business introduces a weekly cash-flow review, assigns owners to overdue invoices, and tracks payment risks in one dashboard.</p>',
      post_status: 'publish',
      post_permalink: 'https://example.com/sample-business-article/'
    },
    post_thumbnail: 'https://example.com/wp-content/uploads/sample-business-cover.jpg',
    post_permalink: 'https://example.com/sample-business-article/',
    executionMode: 'manual'
  }
};

return [{ json: { ...manualPayload, __trigger_source: 'manual' } }];

const marker = String($json.stdout || '').trim();
const source = $('Normalize Webhook or Manual Input').item;

if (marker.includes('DUPLICATE_WEBHOOK')) {
  // Возвращаем 0 items — весь downstream прекращается,
  // поэтому повтор не доходит ни до AI, ни до одной соцсети.
  return [];
}

if (!marker.includes('ALLOW_WEBHOOK') && !marker.includes('ALLOW_MANUAL')) {
  throw new Error(
    'DEDUPE_GUARD_UNKNOWN_RESULT: ' +
    JSON.stringify({ stdout: $json.stdout, stderr: $json.stderr, exitCode: $json.exitCode })
  );
}

return [{
  json: source.json,
  binary: source.binary
}];
